<?php
$u=sr_auth('recruiter');$id=(int)($_GET['id']??0);
$a=sr_one('SELECT a.*,j.title,j.company,u.name,u.email,cp.headline,cp.phone,cp.location,cp.bio,cp.education,cp.experience,cp.portfolio,r.skills AS resume_skills,r.original_name FROM applications a JOIN jobs j ON j.id=a.job_id JOIN users u ON u.id=a.candidate_id LEFT JOIN candidate_profiles cp ON cp.user_id=a.candidate_id LEFT JOIN resumes r ON r.user_id=a.candidate_id WHERE a.id=? AND j.recruiter_id=?',[$id,$u['id']]);
if(!$a):?><div class="panel empty-state"><h2>Không tìm thấy đơn ứng tuyển này</h2><a class="button primary" href="<?=sr_url('applicants')?>">Quay lại ứng viên</a></div><?php else:
$note=sr_one('SELECT note FROM application_notes WHERE application_id=?',[$id]);
$interview=sr_one('SELECT * FROM interviews WHERE application_id=?',[$id])?:[];
$reply=sr_one('SELECT * FROM interview_responses WHERE application_id=?',[$id]);
?><div class="breadcrumbs"><a href="<?=sr_url('applicants')?>">Ứng viên</a><span>/</span><span>Chi tiết hồ sơ</span></div><div class="applicant-header panel"><div class="profile-highlight"><div class="avatar xlarge-avatar"><?=h(sr_initials($a['name']))?></div><div><div class="overline">HỒ SƠ ỨNG VIÊN</div><h1><?=h($a['name'])?></h1><p><?=h($a['headline']?:'Ứng viên SmartRecruit')?></p><p class="muted"><?=h($a['email'])?> <?=!empty($a['phone'])?' · '.h($a['phone']):''?></p></div></div><div class="score-block"><strong><?=$a['score']===null?'—':number_format((float)$a['score'],0).'%'?></strong><small>Điểm so khớp AI (tham khảo)</small></div></div>
<div class="profile-grid"><div class="side-stack"><section class="panel"><h2>Thông tin ứng tuyển</h2><div class="fact"><small>Vị trí</small><strong><?=h($a['title'])?></strong></div><div class="fact"><small>Ngày ứng tuyển</small><strong><?=h(sr_date($a['created_at']))?></strong></div><div class="fact"><small>Khu vực</small><strong><?=h($a['location']?:'Chưa cung cấp')?></strong></div><?php if($a['original_name']):?><a class="button secondary block top-gap" href="<?=sr_url('download',['candidate'=>$a['candidate_id']])?>">Tải CV ứng viên</a><?php else:?><p class="muted">CV đã được ứng viên xóa khỏi hồ sơ.</p><?php endif;?></section><section class="panel"><h2>Đánh giá kỹ năng</h2><div class="insight"><small>Độ tương đồng văn bản</small><strong><?=$a['semantic_score']===null?'Chưa có':h($a['semantic_score']).'%'?></strong></div><div class="insight"><small>Kỹ năng đáp ứng</small><strong><?=$a['skill_score']===null?'Chưa có':h($a['skill_score']).'%'?></strong></div><p class="muted">Phương pháp: 65% độ tương đồng + 35% độ khớp kỹ năng khi xác định được yêu cầu; điểm không xác minh năng lực hay dự đoán trúng tuyển.</p><h3 class="subhead">Kỹ năng đáp ứng</h3><div class="skills success-skills"><?php foreach(sr_skills($a['matched_skills']) as $s):?><span><?=h($s)?></span><?php endforeach;?><?php if(!$a['matched_skills']):?><span>Chưa phát hiện</span><?php endif;?></div><h3 class="subhead">Kỹ năng cần bổ sung</h3><div class="skills missing-skills"><?php foreach(sr_skills($a['missing_skills']) as $s):?><span><?=h($s)?></span><?php endforeach;?><?php if(!$a['missing_skills']):?><span>Không phát hiện</span><?php endif;?></div></section></div>
<div class="side-stack"><section class="panel"><h2>Quản lý hồ sơ ứng tuyển</h2><p class="muted">Thay đổi trạng thái để theo dõi ứng viên trong quy trình tuyển dụng.</p><form method="post" class="stack-form"><?=sr_token()?><input type="hidden" name="action" value="application_status"><input type="hidden" name="back" value="applicant"><input type="hidden" name="back_id" value="<?=$id?>"><input type="hidden" name="id" value="<?=$id?>"><label>Trạng thái<select name="status"><?php foreach(['submitted','reviewing','shortlisted','rejected'] as $st):?><option value="<?=$st?>" <?=$a['status']===$st?'selected':''?>><?=h(sr_status($st))?></option><?php endforeach;?></select></label><button class="button primary">Cập nhật trạng thái</button></form><div class="divider"></div><h3>Lịch phỏng vấn</h3><p class="muted">Ứng viên sẽ nhận được thông báo sau khi lưu lịch.</p><form method="post" class="stack-form"><?=sr_token()?><input type="hidden" name="action" value="interview_save"><input type="hidden" name="back" value="applicant"><input type="hidden" name="back_id" value="<?=$id?>"><input type="hidden" name="application_id" value="<?=$id?>"><label>Thời gian<input type="datetime-local" name="scheduled_at" value="<?=h($interview?date('Y-m-d\TH:i',strtotime($interview['scheduled_at'])):'')?>" required></label><label>Địa điểm phỏng vấn<input name="location" maxlength="255" value="<?=h($interview['location']??'')?>" placeholder="Tại văn phòng ..."></label><label>Link họp trực tuyến<input name="meeting_url" value="<?=h($interview['meeting_url']??'')?>" placeholder="https://meet.google.com/..."></label><label>Trạng thái<select name="status"><?php foreach(['scheduled'=>'Đã lên lịch','completed'=>'Hoàn thành','cancelled'=>'Đã hủy'] as $key=>$val):?><option value="<?=$key?>" <?=($interview['status']??'scheduled')===$key?'selected':''?>><?=h($val)?></option><?php endforeach;?></select></label><label>Lời nhắn gửi ứng viên<textarea name="note" rows="3"><?=h($interview['note']??'')?></textarea></label><button class="button secondary">Lưu lịch phỏng vấn</button></form><?php if($reply):?><div class="privacy-note"><strong>Phản hồi từ ứng viên:</strong> <?=h($reply['response']==='accepted'?'Đã xác nhận tham gia':'Đề nghị đổi lịch')?><?php if($reply['note']):?><p><?=nl2br(h($reply['note']))?></p><?php endif;?><small><?=h($reply['responded_at'])?></small></div><?php endif;?><div class="divider"></div><h3>Ghi chú nội bộ</h3><form method="post" class="stack-form"><?=sr_token()?><input type="hidden" name="action" value="application_note"><input type="hidden" name="back" value="applicant"><input type="hidden" name="back_id" value="<?=$id?>"><input type="hidden" name="id" value="<?=$id?>"><textarea name="note" rows="4" maxlength="5000" placeholder="Ghi nhận nhận xét, lịch phỏng vấn... (không hiển thị cho ứng viên)"><?=h($note['note']??'')?></textarea><button class="button secondary">Lưu ghi chú</button></form></section><section class="panel"><h2>Thông tin hồ sơ</h2><?php foreach(['bio'=>'Giới thiệu','education'=>'Học vấn','experience'=>'Kinh nghiệm / Dự án'] as $key=>$label):?><h3 class="subhead"><?=h($label)?></h3><div class="description"><?=nl2br(h($a[$key]?:'Chưa cập nhật'))?></div><?php endforeach;?><?php if($a['portfolio'] && sr_validate_url($a['portfolio'])):?><a class="text-link top-gap" target="_blank" rel="noopener noreferrer" href="<?=h($a['portfolio'])?>">Xem portfolio ↗</a><?php endif;?></section></div></div><div class="privacy-note">Không sử dụng điểm AI như căn cứ duy nhất để đưa ra quyết định tuyển dụng.</div><?php endif;?>
